import json, random, itertools, re, pathlib, math
random.seed(20261106)
qs=[]

def add(subject, level, unit, question, options, correct, explanation, audience='آموزگار ابتدایی'):
    # preserve unique text, shuffle options deterministically
    options=[str(x) for x in options]
    assert len(options)==4 and len(set(options))==4, (question,options)
    answer_text=str(correct)
    assert answer_text in options, (question,answer_text,options)
    random.shuffle(options)
    ans=options.index(answer_text)
    qs.append({"id":f"AQ{len(qs)+1:04d}","subject":subject,"unit":unit,"level":level,
               "question":question,"options":options,"answer":ans,"explanation":explanation,
               "source":"تألیفی؛ بر پایه مفاهیم عمومی آموزشی و درسی دبستان","audience":audience})

