# 300 mathematics items: arithmetic and number sense
for i in range(60):
    a=12+i; b=11+(i*17)%69; op='+' if i%2==0 else '-'
    if op=='-' and b>a:a,b=b,a
    ans=a+b if op=='+' else a-b
    distract=[ans+10,ans-10,ans+1]
    distract=[x for x in distract if x>=0 and x!=ans]
    while len(set(distract))<3:distract.append(ans+len(distract)+2)
    add("ریاضی","آسان" if i<30 else "متوسط","جمع و تفریق",f"حاصل {a} {op} {b} کدام است؟",[ans]+distract[:3],ans,f"با انجام عمل {('جمع' if op=='+' else 'تفریق')} داریم: {a} {op} {b} = {ans}.")
for i in range(60):
    a=3+(i%17); b=4+(i//17); ans=a*b
    distract=[ans+1,ans+3,ans+7]
    add("ریاضی","متوسط","ضرب",f"حاصل ضرب {a} در {b} چند می‌شود؟",[ans]+distract,ans,f"{a} گروهِ {b}تایی برابر {a}×{b}={ans} است.")
for i in range(40):
    b=2+(i%11); ans=3+(i//11); a=b*ans
    distract=[ans+1,ans-1,ans+2]
    add("ریاضی","متوسط","تقسیم",f"اگر {a} مهره را به طور مساوی میان {b} نفر تقسیم کنیم، سهم هر نفر چند مهره است؟",[ans]+distract,ans,f"تقسیم مساوی یعنی {a} ÷ {b} = {ans}.")
for i in range(40):
    combos=[(d,x,y) for d in [2,3,4,5,6,8,10,12] for x in range(1,d) for y in range(1,d) if x+y<=d]
    den,n1,n2=combos[i*3 % len(combos)]
    num=n1+n2; from fractions import Fraction
    val=Fraction(num,den); ans=f"{val.numerator}/{val.denominator}"
    candidates=[Fraction(max(0,num-1),den),Fraction(max(0,num-2),den+1),Fraction(num+1,den+2),Fraction(n1,den+1),Fraction(n2,den+2),Fraction(max(0,num-1),den+3),Fraction(num+2,den+5),Fraction(1,den+1)]
    wrong=[]
    for f in candidates:
        if f!=val:
            label=f"{f.numerator}/{f.denominator}"
            if label not in wrong: wrong.append(label)
        if len(wrong)==3: break
    add("ریاضی","متوسط","جمع کسرهای هم‌مخرج",f"حاصل {n1}/{den} + {n2}/{den} در ساده‌ترین شکل چیست؟",[ans]+wrong,ans,f"مخرج‌های برابر را نگه می‌داریم، صورت‌ها را جمع می‌کنیم: {n1}+{n2}={num}؛ سپس کسر را ساده می‌کنیم.")
for i in range(20):
    base,p=[(b,p) for b in [50,80,100,120,150,200,250,300] for p in [10,20,25,50]][i]; ans=base*p//100
    distract=[ans+1,ans+3,ans-2]
    add("ریاضی","متوسط","درصد",f"{p} درصدِ عدد {base} برابر با چند است؟",[ans]+distract,ans,f"برای محاسبه درصد: {base}×{p}/100={ans}.")
for i in range(30):
    side=3+i; ans=4*side
    add("ریاضی","آسان","محیط مربع",f"محیط مربعی با ضلع {side} سانتی‌متر چند سانتی‌متر است؟",[ans,2*side+1,side*side+5,ans+7],ans,f"محیط مربع برابر چهار برابر ضلع است: ۴×{side}={ans} سانتی‌متر.")
for i in range(20):
    a=3+i; b=3+(i*7)%17; ans=a*b
    add("ریاضی","متوسط","مساحت مستطیل",f"مساحت مستطیلی با طول {a} و عرض {b} سانتی‌متر چند سانتی‌متر مربع است؟",[ans,ans+1,ans+3,ans+10],ans,f"مساحت مستطیل = طول × عرض = {a}×{b}={ans} سانتی‌متر مربع.")
for i in range(10):
    h=20+2*i; ans=h//2
    add("ریاضی","متوسط","نصف و تقسیم",f"نصفِ {h} چند است؟",[ans,h,ans+5,ans-5],ans,f"نصف یعنی تقسیم بر ۲؛ {h}÷۲={ans}.")
for i in range(20):
    n=random.randint(100,999); digit=(n//10)%10; ans=digit
    wrong=[(digit+1)%10,(digit+3)%10,(digit+7)%10]
    add("ریاضی","آسان","ارزش مکانی",f"در عدد {n}، رقم دهگان کدام است؟",[ans]+wrong,ans,f"رقم دهگان در جایگاه دوم از سمت راست قرار دارد؛ در عدد {n} رقم دهگان {digit} است.")
assert len([x for x in qs if x['subject']=="ریاضی"])==300

