("کدام بخش گیاه معمولاً آب و مواد معدنی را از خاک جذب می‌کند؟","ریشه",["گلبرگ","میوه","دانه"],"ریشه و تارهای کشنده آن در جذب آب و مواد معدنی نقش دارند."),
("بیشتر تبادل گازها در برگ از چه ساختارهایی انجام می‌شود؟","روزنه‌ها",["رگبرگ‌ها","ریشه‌چه‌ها","گلبرگ‌ها"],"روزنه‌های برگ امکان تبادل گازها با محیط را فراهم می‌کنند."),
("کدام بخش گیاه معمولاً آب را از ریشه به برگ‌ها می‌رساند؟","ساقه و آوندهای آن",["گلبرگ","پوسته دانه","میوه"],"آوندهای ساقه آب و مواد محلول را در گیاه جابه‌جا می‌کنند."),
("جاندارانی که غذای خود را از مواد غیرزنده می‌سازند در زنجیره غذایی چه نام دارند؟","تولیدکننده",["مصرف‌کننده دوم","شکارچی رأس","تجزیه‌کننده"],"گیاهان سبز نمونه مهم تولیدکنندگان‌اند."),
("قارچ‌ها و بسیاری از باکتری‌ها در اکوسیستم چه نقشی دارند؟","تجزیه مواد آلی",["تولید نور خورشید","توقف چرخه مواد","ساختن سنگ‌های آذرین"],"تجزیه‌کنندگان بقایای جانداران را می‌شکنند و مواد را به محیط بازمی‌گردانند."),
("تبدیل آب مایع به بخار آب چه نام دارد؟","تبخیر",["میعان","انجماد","ذوب"],"در تبخیر، مایع به گاز تبدیل می‌شود."),
("تبدیل بخار آب به قطره‌های مایع چه نام دارد؟","میعان",["تبخیر","تصعید","ذوب"],"با سردشدن بخار آب، میعان و تشکیل قطره رخ می‌دهد."),
("تبدیل آب مایع به یخ چه نام دارد؟","انجماد",["ذوب","تبخیر","میعان"],"در انجماد، مایع به جامد تبدیل می‌شود."),
("تبدیل یخ به آب مایع چه نام دارد؟","ذوب",["انجماد","میعان","رسوب‌گذاری"],"با گرفتن گرما، یخ ذوب می‌شود."),
("کدام حالت ماده شکل و حجم تقریباً ثابتی دارد؟","جامد",["گاز","مایع","بخار"],"جامد شکل و حجم معین دارد."),
("کدام حالت ماده حجم معین دارد اما شکل ظرف را می‌گیرد؟","مایع",["جامد","گاز","پلاسما"],"مایع حجم تقریباً ثابت دارد و شکل ظرف را می‌گیرد."),
("کدام حالت ماده شکل و حجم ثابتی ندارد و فضا را پر می‌کند؟","گاز",["جامد","مایع","بلور"],"گاز در دسترس خود پخش می‌شود و شکل و حجم ثابتی ندارد."),
("برای اندازه‌گیری دمای هوا از چه وسیله‌ای استفاده می‌شود؟","دماسنج",["ترازو","قطب‌نما","خط‌کش"],"دماسنج برای سنجش دما به کار می‌رود."),
("برای اندازه‌گیری جرم یک جسم از چه وسیله‌ای استفاده می‌شود؟","ترازو",["دماسنج","زمان‌سنج","قطب‌نما"],"ترازو جرم را اندازه‌گیری می‌کند."),
("کدام نیرو اجسام را به سوی زمین می‌کشد؟","گرانش",["نیروی الکتریکی فقط","نیروی صوتی","نور"],"گرانش میان جرم‌ها جاذبه ایجاد می‌کند."),
("اصطکاک معمولاً در برابر چه چیزی عمل می‌کند؟","حرکت نسبی دو سطح",["نور خورشید","جرم جسم","رنگ سطح"],"اصطکاک در برابر لغزش یا حرکت نسبی سطوح مقاومت می‌کند."),
("کدام ماده معمولاً رسانای خوب جریان برق است؟","مس",["لاستیک","چوب خشک","شیشه"],"مس فلزی رساناست و در سیم‌ها کاربرد فراوان دارد."),
("کدام ماده معمولاً عایق الکتریکی است؟","لاستیک",["مس","آلومینیوم","آهن"],"لاستیک جریان الکتریکی را به‌خوبی عبور نمی‌دهد."),
("برای کامل‌شدن مدار ساده الکتریکی چه چیزی لازم است؟","مسیر بسته",["سیم قطع‌شده","کلید همیشه باز","نبود باتری"],"جریان در مدار بسته می‌تواند عبور کند."),
("اگر کلید مدار باز باشد، چه وضعی برای جریان رخ می‌دهد؟","جریان برقرار نمی‌شود",["جریان بی‌نهایت می‌شود","باتری شارژ می‌شود","لامپ همیشه روشن می‌ماند"],"کلید باز، مسیر جریان را قطع می‌کند."),
("آهن‌ربا کدام ماده را به‌طور معمول جذب می‌کند؟","آهن",["کاغذ","چوب","شیشه"],"آهن از مواد فرومغناطیس است و به آهن‌ربا جذب می‌شود."),
("دو قطب هم‌نام آهن‌ربا چه رفتاری دارند؟","یکدیگر را دفع می‌کنند",["همیشه جذب می‌کنند","ناپدید می‌شوند","بی‌اثرند"],"قطب‌های هم‌نام دفع و قطب‌های ناهم‌نام جذب می‌کنند."),
("نور در محیط شفاف و یکنواخت معمولاً چگونه حرکت می‌کند؟","در خط راست",["همیشه دایره‌ای","فقط رو به پایین","به شکل زیگزاگ تصادفی"],"در محیط یکنواخت، نور به صورت خط مستقیم منتشر می‌شود."),
("سایه در کدام سمت جسم کدر تشکیل می‌شود؟","سمت مخالف منبع نور",["همیشه سمت منبع نور","داخل منبع نور","فقط بالای جسم"],"جسم کدر نور را مسدود می‌کند و پشت آن سایه تشکیل می‌شود."),
("بازتاب نور از آینه چگونه است؟","نور را بازمی‌تاباند",["نور را به صدا تبدیل می‌کند","همه نور را می‌بلعد","نور را به ماده تبدیل می‌کند"],"سطح صاف آینه بخش زیادی از نور را بازمی‌تاباند."),
("صدا چگونه در هوا منتشر می‌شود؟","به صورت موج‌های ارتعاشی",["به صورت نور","بدون ارتعاش","فقط از راه خلأ"],"صدا موج مکانیکی است و برای انتشار به محیط مادی نیاز دارد."),
("آیا صدا در خلأ منتشر می‌شود؟","خیر؛ به محیط مادی نیاز دارد",["بله، سریع‌تر از نور","فقط در شب","فقط با آهن‌ربا"],"صدا برای انتقال ارتعاش به محیط مادی نیازمند است."),
("اندام اصلی تبادل اکسیژن و دی‌اکسیدکربن در انسان چیست؟","ریه‌ها",["معده","کلیه‌ها","استخوان‌ها"],"تبادل گازها در کیسه‌های هوایی ریه انجام می‌شود."),
("کدام اندام خون را در بدن به جریان می‌اندازد؟","قلب",["معده","کبد","پوست"],"قلب با انقباض‌های منظم خون را پمپ می‌کند."),
("وظیفه اصلی گلبول‌های قرمز خون چیست؟","حمل بیشتر اکسیژن",["ساخت استخوان","هضم غذا","تولید صفرا"],"هموگلوبین گلبول قرمز اکسیژن را حمل می‌کند."),
("هضم مکانیکی غذا در دهان با کمک چه چیزی انجام می‌شود؟","دندان‌ها",["ریه‌ها","کلیه‌ها","قلب"],"دندان‌ها غذا را خرد می‌کنند و جویدن هضم مکانیکی است."),
("کدام اندام با تولید صفرا به هضم چربی‌ها کمک می‌کند؟","کبد",["قلب","ریه","مغز"],"کبد صفرا تولید می‌کند و صفرا در گوارش چربی‌ها نقش دارد."),
("بیشتر جذب مواد غذایی گوارش‌یافته در کدام بخش انجام می‌شود؟","روده باریک",["مری","دهان","روده بزرگ"],"روده باریک سطح جذب گسترده‌ای دارد."),
("کدام دستگاه بدن پیام‌ها را با مغز و نخاع هماهنگ می‌کند؟","دستگاه عصبی",["دستگاه گوارش","دستگاه اسکلتی","دستگاه دفع ادرار"],"دستگاه عصبی اطلاعات را دریافت و پاسخ‌ها را هماهنگ می‌کند."),
("استخوان‌ها همراه ماهیچه‌ها چه کمکی به بدن می‌کنند؟","پشتیبانی و حرکت",["تولید نور","هضم مستقیم غذا","تصفیه هوا"],"اسکلت تکیه‌گاه بدن است و با ماهیچه‌ها حرکت را ممکن می‌کند."),
("کدام رفتار به سلامت دندان‌ها کمک می‌کند؟","مسواک‌زدن منظم با خمیردندان مناسب",["خوردن مداوم مواد قندی بدون شست‌وشو","استفاده از دندان برای شکستن اجسام سخت","نخوردن آب"],"بهداشت دهان و کاهش مصرف قند به سلامت دندان کمک می‌کند."),
("واکسیناسیون چه نقشی در پیشگیری از برخی بیماری‌ها دارد؟","آماده‌کردن دستگاه ایمنی برای شناسایی عامل بیماری‌زا",["جایگزینی کامل خواب","از بین بردن همه میکروب‌های محیط","درمان فوری تمام بیماری‌ها"],"واکسن دستگاه ایمنی را برای پاسخ بهتر به عامل مشخص آماده می‌کند."),
("کدام مورد منبع انرژی تجدیدپذیر است؟","باد",["زغال‌سنگ","نفت خام","گاز طبیعی"],"باد با فرایندهای طبیعی پیوسته تجدید می‌شود."),
("سوختن سوخت‌های فسیلی معمولاً چه گازی را به مقدار زیادی وارد هوا می‌کند؟","دی‌اکسیدکربن",["هلیم","نئون","آرگون خالص"],"احتراق سوخت‌های کربن‌دار دی‌اکسیدکربن تولید می‌کند."),
("کدام کار به کاهش مصرف آب کمک می‌کند؟","بستن شیر هنگام مسواک‌زدن",["بازگذاشتن شیر آب","شستن خودرو با شلنگِ باز طولانی","نشت آب را نادیده‌گرفتن"],"بستن شیر در زمان عدم نیاز از هدررفت آب جلوگیری می‌کند."),
("لایه ازن در جو چه نقشی مهمی دارد؟","جذب بخش زیادی از پرتو فرابنفش زیان‌آور",["تولید اکسیژن برای همه جانداران به تنهایی","ایجاد میدان گرانش","جلوگیری از همه بارش‌ها"],"ازن استراتوسفری بخشی از پرتو فرابنفش را جذب می‌کند."),
("سنگ‌های آذرین از چه فرایندی به وجود می‌آیند؟","سرد و سخت‌شدن مواد مذاب",["فشرده‌شدن برف","تبخیر آب دریا","پوسیدن برگ‌ها"],"سنگ آذرین از سردشدن و انجماد ماگما یا گدازه تشکیل می‌شود."),
("سنگ‌های رسوبی معمولاً چگونه تشکیل می‌شوند؟","تراکم و سیمانی‌شدن رسوبات",["ذوب فلزها","سوختن خاک","تبخیر اکسیژن"],"رسوبات در گذر زمان فشرده و به هم چسبیده می‌شوند."),
("کدام لایه زمین در زیر پوسته قرار دارد؟","گوشته",["هسته داخلی","جو","اقیانوس"],"گوشته زیر پوسته و بالای هسته زمین قرار دارد."),
("زمین تقریباً در چه مدتی یک بار به دور محور خود می‌چرخد؟","۲۴ ساعت",["یک ماه","یک سال","۱۲ سال"],"چرخش زمین به دور محور خود تقریباً یک شبانه‌روز طول می‌کشد."),
("علت اصلی پیدایش شب و روز چیست؟","چرخش زمین به دور محور خود",["چرخش ماه به دور زمین","دورشدن خورشید در شب","تغییر اندازه خورشید"],"هر بخش زمین با چرخش به سوی خورشید روز و با دورشدن از آن شب را تجربه می‌کند."),
("زمین تقریباً در چه مدتی یک بار به دور خورشید می‌گردد؟","یک سال",["یک روز","یک هفته","یک ماه"],"گردش زمین به دور خورشید حدود ۳۶۵ روز و یک‌چهارم روز طول می‌کشد."),
("ماه نور خود را چگونه دریافت می‌کند؟","با بازتاب نور خورشید",["با تولید نور مانند خورشید","از برق زمین","از ستارگان دور به تنهایی"],"ماه منبع نور مستقل نیست؛ نور خورشید را بازمی‌تاباند."),
("کدام ستاره به زمین نزدیک‌تر از ستارگان دیگر است؟","خورشید",["ستاره قطبی","شِعرای یمانی","ستاره‌ای در کهکشان دیگر"],"خورشید نزدیک‌ترین ستاره به زمین است."),
("بارش باران بخشی از کدام چرخه طبیعی است؟","چرخه آب",["چرخه سنگ فقط","چرخه شبانه‌روز","چرخه الکتریکی"],"تبخیر، میعان و بارش بخش‌های چرخه آب‌اند."),
("ابرها عمدتاً از چه چیزی تشکیل می‌شوند؟","قطره‌های ریز آب یا بلورهای یخ",["دود جامد","خاکستر آتشفشان همیشه","اکسیژن خالص"],"ابرها از قطره‌های ریز آب و/یا بلورهای یخ معلق تشکیل می‌شوند."),
("کدام وسیله برای اندازه‌گیری سرعت باد به کار می‌رود؟","بادسنج",["باران‌سنج","دماسنج","ترازو"],"بادسنج سرعت باد را اندازه‌گیری می‌کند."),
("کدام جاندار در گروه مهره‌داران قرار می‌گیرد؟","ماهی",["کرم خاکی","حلزون","عروس دریایی"],"ماهی ستون مهره دارد و مهره‌دار است."),
("کدام گروه جانوران معمولاً بدن خود را با پر پوشانده‌اند؟","پرندگان",["خزندگان","دوزیستان","ماهی‌ها"],"پر ویژگی شاخص پرندگان است."),
("بیشتر پستانداران نوزاد خود را چگونه تغذیه می‌کنند؟","با شیر مادر",["با نور خورشید","با خاک","با آب شور"],"غدد شیری پستانداران شیر تولید می‌کند."),
("دوزیستان معمولاً بخشی از زندگی خود را در کجا می‌گذرانند؟","آب و خشکی",["فقط بیابان خشک","فقط آسمان","فقط زیر یخ"],"بسیاری از دوزیستان در آب تولیدمثل می‌کنند و در خشکی نیز زندگی دارند."),
("کدام جانور بی‌مهره است؟","پروانه",["گربه","قورباغه","کبوتر"],"پروانه ستون مهره ندارد و حشره‌ای بی‌مهره است."),
("کدام سازگاری به شتر برای زندگی در بیابان کمک می‌کند؟","تحمل کم‌آبی و ویژگی‌های مناسب بدن",["نیاز همیشگی به آب فراوان","داشتن آبشش","ناتوانی از تحمل گرما"],"شتر مجموعه‌ای از سازگاری‌ها برای شرایط خشک دارد."),
("تنوع زیستی به چه معناست؟","گوناگونی جانداران و زیستگاه‌ها",["یکسان‌بودن همه جانداران","فقط تعداد انسان‌ها","فقط رنگ گل‌ها"],"تنوع زیستی به گوناگونی حیات در سطوح مختلف اشاره دارد."),
("در یک زیست‌بوم، زنجیره غذایی نشان‌دهنده چیست؟","انتقال ماده و انرژی از راه تغذیه",["تغییر جهت باد","حرکت سیاره‌ها","تولید سنگ"],"زنجیره غذایی رابطه تغذیه و انتقال انرژی را نشان می‌دهد."),
("کدام عمل به حفاظت از زیستگاه جانوران کمک می‌کند؟","جلوگیری از تخریب زیستگاه",["ریختن زباله در طبیعت","شکار بی‌رویه","سوزاندن پوشش گیاهی"],"حفظ زیستگاه برای بقا و تنوع گونه‌ها ضروری است."),
("کدام مورد نمونه‌ای از تغییر فیزیکی است؟","خردشدن کاغذ",["سوختن کاغذ","زنگ‌زدن آهن","پختن تخم‌مرغ"],"در خردشدن کاغذ ماده جدیدی ساخته نمی‌شود و تغییر فیزیکی است."),
("سوختن چوب چه نوع تغییری است؟","تغییر شیمیایی",["تغییر فیزیکی برگشت‌پذیر ساده","ذوب‌شدن","انجماد"],"در سوختن مواد جدیدی مانند خاکستر و گازها ایجاد می‌شود."),
("برای جداکردن براده آهن از ماسه چه ابزاری مناسب است؟","آهن‌ربا",["صافی پارچه‌ای به تنهایی","دماسنج","قاشق چوبی"],"براده آهن جذب آهن‌ربا می‌شود اما ماسه چنین خاصیتی ندارد."),
("برای جداکردن شن از آب معمولاً چه روشی به کار می‌رود؟","صاف‌کردن",["ذوب‌کردن","آهن‌ربایی","تبخیر کامل شن"],"ذرات نامحلول شن با صافی از آب جدا می‌شوند."),
("کدام منبع آب شیرین برای بسیاری از رودها و چشمه‌ها مهم است؟","بارش و ذوب برف",["نفت زیرزمینی","آب شور اقیانوس فقط","گاز طبیعی"],"بارش و ذوب برف آب سطحی و زیرزمینی را تغذیه می‌کنند."),
("کدام ویژگی آب آشامیدنی سالم مهم است؟","نداشتن مقدار خطرناک آلودگی و عوامل بیماری‌زا",["داشتن بوی شدید نامطبوع","وجود زباله قابل مشاهده","داشتن رنگ غیرعادی"],"آب آشامیدنی باید از نظر میکروبی و شیمیایی ایمن باشد."),
("چرا باید زباله را از رودخانه دور نگه داشت؟","برای جلوگیری از آلودگی آب و آسیب به جانداران",["برای افزایش شوری آب","برای کم‌کردن اکسیژن همه گیاهان خشکی","برای گرم‌کردن رودخانه"],"زباله‌ها می‌توانند آب را آلوده و زیست جانداران را مختل کنند."),
("کدام رفتار در هنگام زلزله داخل ساختمان ایمن‌تر است؟","پناه‌گرفتن زیر میز محکم و محافظت از سر",["ایستادن کنار پنجره","استفاده از آسانسور","دویدن روی پله هنگام لرزش"],"در زمان لرزش باید سر و گردن محافظت و از شیشه و اشیای سقوط‌کننده دور شد."),
("هنگام آتش‌سوزی در ساختمان، استفاده از آسانسور چه وضعی دارد؟","نباید استفاده شود",["همیشه بهترین راه خروج است","فقط برای کودکان مجاز است","از پله امن‌تر است"],"آسانسور ممکن است از کار بیفتد یا در معرض دود و آتش قرار گیرد؛ مسیر خروج ایمن باید دنبال شود."),
("چرا استفاده از کلاه ایمنی هنگام دوچرخه‌سواری مهم است؟","کاهش خطر آسیب سر",["افزایش وزن دوچرخه","جلوگیری از خیس‌شدن لباس","افزایش سرعت حرکت"],"کلاه مناسب می‌تواند شدت آسیب سر در برخی برخوردها را کاهش دهد."),
("کدام کار به پیشگیری از گسترش بیماری‌های عفونی کمک می‌کند؟","شستن درست دست‌ها",["استفاده مشترک از لیوان آلوده","سرفه‌کردن بدون پوشاندن دهان","بی‌توجهی به بهداشت"],"شستن دست‌ها انتقال بسیاری از عوامل بیماری‌زا را کاهش می‌دهد."),
("مواد مغذی و انرژی مورد نیاز بدن از چه راهی تأمین می‌شود؟","غذای متنوع و متعادل",["فقط شیرینی","فقط نوشابه","فقط مکمل بدون غذا"],"رژیم متنوع گروه‌های غذایی مختلف را برای نیازهای بدن فراهم می‌کند."),
("فیبر غذایی بیشتر در کدام گروه خوراکی‌ها یافت می‌شود؟","میوه‌ها، سبزی‌ها و غلات کامل",["روغن خالص","شکر سفید خالص","آب ساده"],"مواد گیاهی کامل معمولاً منابع خوب فیبر هستند."),
("چرا خواب کافی برای دانش‌آموزان مهم است؟","به رشد، توجه و یادگیری کمک می‌کند",["نیاز بدن به آب را حذف می‌کند","همه بیماری‌ها را درمان می‌کند","جایگزین تغذیه می‌شود"],"خواب کافی از کارکرد مغز و سلامت عمومی حمایت می‌کند."),
("کدام بخش چشم نور را وارد چشم می‌کند؟","مردمک",["لاله گوش","زبان","مینا"],"نور از مردمک وارد چشم می‌شود و اندازه آن با عنبیه تنظیم می‌شود."),
("گوش داخلی در کدام کار نقش مهمی دارد؟","شنوایی و تعادل",["هضم غذا","تصفیه خون","ساخت گلبول قرمز"],"ساختارهای گوش داخلی در شنیدن و حفظ تعادل نقش دارند."),
("کدام ابزار برای مشاهده اجسام بسیار ریز مناسب است؟","میکروسکوپ",["تلسکوپ","قطب‌نما","ساعت"],"میکروسکوپ تصویر اجسام کوچک را بزرگ می‌کند."),
("کدام ابزار برای مشاهده اجرام دور آسمانی به کار می‌رود؟","تلسکوپ",["میکروسکوپ","ترازو","دماسنج"],"تلسکوپ برای گردآوری و مشاهده نور اجرام دوردست استفاده می‌شود."),
("کدام سیاره به خورشید نزدیک‌تر است؟","عطارد",["زمین","مریخ","مشتری"],"عطارد نزدیک‌ترین سیاره به خورشید است."),
("کدام سیاره به داشتن حلقه‌های بزرگ و آشکار معروف است؟","زحل",["عطارد","زمین","مریخ"],"زحل سامانه حلقه‌ای چشمگیری دارد."),
("خورشید در مرکز کدام سامانه قرار دارد؟","منظومه شمسی",["کهکشان آندرومدا","یک اتم","اقیانوس اطلس"],"خورشید ستاره مرکزی منظومه شمسی است."),
("چرا فصل‌ها در زمین به وجود می‌آیند؟","به دلیل میل محور زمین و گردش آن به دور خورشید",["به دلیل نزدیک و دورشدن روزانه ماه","به دلیل خاموش و روشن‌شدن خورشید","به دلیل تغییر اندازه زمین"],"میل محور زمین هنگام گردش سالانه، زاویه تابش و طول روز را تغییر می‌دهد."),
("کدام بخش از خاک برای رشد بسیاری از گیاهان اهمیت دارد؟","مواد معدنی، آب، هوا و مواد آلی",["فقط پلاستیک","فقط شیشه خردشده","فقط نمک خالص"],"خاک سالم ترکیبی از مواد معدنی، مواد آلی، آب و هواست."),
("کرم خاکی چگونه می‌تواند به خاک کمک کند؟","با جابه‌جایی و هوادهی خاک و تجزیه مواد آلی",["با تولید نور","با تبدیل خاک به فلز","با حذف همه باکتری‌ها"],"فعالیت کرم خاکی به ساختار و تهویه خاک کمک می‌کند."),
("فرسایش خاک یعنی چه؟","جابه‌جایی و از دست‌رفتن ذرات خاک بر اثر آب یا باد",["ساختن خاک در یک لحظه","تبدیل خاک به نور","یخ‌زدن همیشگی زمین"],"آب و باد می‌توانند ذرات خاک را جابه‌جا کنند."),
("کدام روش به کاهش فرسایش خاک در دامنه‌ها کمک می‌کند؟","حفظ پوشش گیاهی",["ازبین‌بردن همه درختان","چرای بی‌رویه","سوزاندن گیاهان"],"ریشه گیاهان خاک را نگه می‌دارد و پوشش گیاهی سرعت رواناب را کم می‌کند."),
("کدام انرژی در باتری ذخیره می‌شود؟","انرژی شیمیایی",["انرژی صوتی","انرژی باد","انرژی نور ماه"],"باتری انرژی شیمیایی را به انرژی الکتریکی تبدیل می‌کند."),
("در پنکه برقی، انرژی الکتریکی عمدتاً به چه انرژی‌ای تبدیل می‌شود؟","حرکت مکانیکی",["انرژی هسته‌ای","انرژی شیمیایی غذا","نور خورشید"],"موتور پنکه انرژی الکتریکی را به حرکت پره‌ها تبدیل می‌کند."),
("کدام وسیله انرژی خورشید را به برق تبدیل می‌کند؟","سلول خورشیدی",["دماسنج","قطب‌نما","صافی"],"سلول فتوولتائیک نور را به انرژی الکتریکی تبدیل می‌کند."),
("چرا لباس تیره در آفتاب معمولاً گرم‌تر از لباس روشن می‌شود؟","نور بیشتری جذب می‌کند",["همه نور را بازمی‌تاباند","جرم زمین را تغییر می‌دهد","باد را متوقف می‌کند"],"سطوح تیره معمولاً سهم بیشتری از تابش را جذب می‌کنند."),
("کدام سطح معمولاً نور را بهتر بازتاب می‌دهد؟","سطح صاف و براق",["سطح زبر و تیره همیشه","پارچه پشمی مات","شن خشک"],"سطوح صاف و براق بازتاب منظم‌تری ایجاد می‌کنند."),
("چرا دسته قابلمه اغلب از ماده عایق ساخته می‌شود؟","برای کاهش انتقال گرما به دست",["برای افزایش برق‌رسانی","برای جذب آب غذا","برای سنگین‌کردن قابلمه"],"مواد عایق انتقال گرما را کند می‌کنند و خطر سوختگی را کاهش می‌دهند."),
("انتقال گرما در طول یک قاشق فلزی از قسمت داغ به قسمت سرد چه نام دارد؟","رسانش",["همرفت","تابش","تبخیر"],"در رسانش گرما از راه تماس و برخورد ذرات منتقل می‌شود."),
("انتقال گرما به وسیله حرکت مایع یا گاز چه نام دارد؟","همرفت",["رسانش","انجماد","بازتاب"],"در همرفت، جابه‌جایی سیال انرژی گرمایی را منتقل می‌کند."),
("گرمای خورشید چگونه از فضای تقریباً خالی به زمین می‌رسد؟","تابش",["رسانش از هوا","همرفت در خلأ","اصطکاک"],"تابش برای انتقال انرژی به محیط مادی نیاز ندارد."),
("کدام یک از موارد زیر نمونه‌ای از اهرم است؟","الاکلنگ",["چراغ قوه","لیوان آب","آینه تخت"],"الاکلنگ حول تکیه‌گاه می‌چرخد و نمونه‌ای از اهرم است."),
("سطح شیبدار چه کمکی می‌کند؟","جابجایی بار با نیروی کمتر و مسیر طولانی‌تر",["حذف کامل کار", "تبدیل جرم به انرژی", "افزایش وزن جسم"],"سطح شیبدار نیروی لازم را کاهش می‌دهد اما مسیر را طولانی‌تر می‌کند."),
("قرقره ثابت ساده بیشتر چه کمکی می‌کند؟","تغییر جهت نیرو",["حذف وزن جسم","تولید انرژی رایگان","کاهش جرم جسم"],"قرقره ثابت جهت نیروی واردشده را تغییر می‌دهد."),
("فرایند انتقال دانه گرده از بساک به کلاله گل چه نام دارد؟","گرده‌افشانی",["جوانه‌زنی","فتوسنتز","تنفس"],"گرده‌افشانی انتقال دانه گرده به کلاله گل است."),
("برای جوانه‌زنی بسیاری از دانه‌ها کدام شرایط لازم است؟","آب، اکسیژن و دمای مناسب",["نور شدید در همه گونه‌ها","خاک شور و بدون آب","یخ‌زدگی دائمی"],"بسیاری از دانه‌ها برای جوانه‌زنی به آب، اکسیژن و دمای مناسب نیاز دارند؛ نیاز نوری بسته به گونه متفاوت است."),
("کدام جانور نقش مهمی در گرده‌افشانی برخی گیاهان دارد؟","زنبور عسل",["کوسه","مارمولک","کرم نواری"],"زنبورها هنگام تغذیه از شهد می‌توانند گرده را میان گل‌ها منتقل کنند."),
("کدام بخش گل پس از لقاح در بسیاری از گیاهان به میوه تبدیل می‌شود؟","تخمدان",["کاسبرگ","گلبرگ","پرچم"],"تخمدان گل پس از لقاح معمولاً به میوه تبدیل می‌شود."),
("دانه گیاه معمولاً چه چیزی را در خود جای می‌دهد؟","جنین گیاه و ذخیره غذایی",["ریشه کامل گیاه بالغ","خاک آماده","آب دریا"],"دانه جنین گیاه و در بسیاری از گونه‌ها ذخیره غذایی دارد."),
("کدام گروه جانوران دمای بدن خود را تا حد زیادی با محیط تنظیم می‌کنند؟","بسیاری از خزندگان",["همه پرندگان","همه پستانداران","همه ماهیان خون‌گرم"],"بسیاری از خزندگان جانوران خونسرد/دگرما هستند و دمای بدنشان به محیط وابسته‌تر است."),
("کدام جانور معمولاً از راه آبشش اکسیژن محلول آب را دریافت می‌کند؟","ماهی",["گنجشک","گربه","مار"],"بیشتر ماهی‌ها با آبشش اکسیژن محلول در آب را جذب می‌کنند."),
("کدام ساختار بدن انسان از مغز محافظت می‌کند؟","جمجمه",["دنده‌ها","استخوان ران","مهره‌های کمری"],"استخوان‌های جمجمه کاسه‌ای محافظ پیرامون مغز ایجاد می‌کنند."),
("قفسه سینه از کدام اندام‌های مهم محافظت می‌کند؟","قلب و ریه‌ها",["معده و روده‌ها به طور کامل","کلیه‌ها به طور کامل","مغز"],"دنده‌ها و جناغ از قلب و بخش‌هایی از ریه‌ها محافظت می‌کنند."),
("کدام اندام در تنظیم مقدار آب بدن و دفع مواد زائد خون نقش دارد؟","کلیه‌ها",["ریه‌ها","معده","پوست سر"],"کلیه‌ها خون را پالایش می‌کنند و در تنظیم آب و املاح بدن نقش دارند."),
("کدام ویتامین با قرارگرفتن پوست در معرض نور خورشید در بدن ساخته می‌شود؟","ویتامین D",["ویتامین C","ویتامین B12","ویتامین K فقط از نور"],"پوست با کمک پرتو فرابنفش B می‌تواند ویتامین D بسازد."),
("کدام حس بیشتر به کمک گیرنده‌های زبان و بینی در تشخیص مزه و بو نقش دارد؟","چشایی و بویایی",["شنوایی و بینایی","لامسه و تعادل","بینایی و تعادل"],"چشایی و بویایی با هم در درک طعم غذا نقش دارند."),
("واحد رایج اندازه‌گیری طول در دستگاه SI چیست؟","متر",["کیلوگرم","ثانیه","لیتر"],"متر واحد پایه طول در دستگاه بین‌المللی یکاهاست."),
("واحد رایج اندازه‌گیری زمان در دستگاه SI چیست؟","ثانیه",["متر","کیلوگرم","درجه سلسیوس"],"ثانیه واحد پایه زمان در دستگاه SI است."),
("اگر به جسم ساکن نیروی برآیند وارد نشود، چه چیزی درباره حرکت آن درست است؟","ساکن می‌ماند",["حتماً شتاب می‌گیرد","ناگهان ناپدید می‌شود","جرمش صفر می‌شود"],"طبق قانون اول نیوتن، جسم در نبود نیروی برآیند حالت حرکت خود را حفظ می‌کند."),
("کدام نوع انرژی در فنر فشرده یا کشیده ذخیره می‌شود؟","انرژی پتانسیل کشسانی",["انرژی صوتی","انرژی نورانی","انرژی شیمیایی"],"فنر تغییرشکل‌یافته می‌تواند انرژی پتانسیل کشسانی ذخیره کند."),
("صدای زیر نسبت به صدای بم چه ویژگی‌ای دارد؟","بسامد بیشتری دارد",["بسامد کمتری دارد","همیشه بلندتر است","سرعت نور بیشتری دارد"],"زیر و بمی صدا با بسامد موج صوتی مرتبط است."),
("شدت صدای بلندتر معمولاً با کدام ویژگی موج مرتبط است؟","دامنه بیشتر",["بسامد صفر","طول موج نوری","جرم بیشتر هوا"],"در شرایط مشابه، دامنه بیشتر موج صوتی با صدای بلندتر همراه است."),
("خورشیدگرفتگی زمانی رخ می‌دهد که چه جرمی میان زمین و خورشید قرار گیرد؟","ماه",["مریخ","مشتری","زحل"],"در خورشیدگرفتگی، ماه از دید ناظر زمینی مقابل خورشید قرار می‌گیرد."),
("ماه‌گرفتگی زمانی رخ می‌دهد که زمین در کجا قرار گیرد؟","میان خورشید و ماه",["میان ماه و مریخ","پشت خورشید از دید ماه","درون خورشید"],"در ماه‌گرفتگی، زمین سایه خود را بر ماه می‌اندازد."),
("قطب‌نمای مغناطیسی در حالت آزاد تقریباً در راستای کدام جهت قرار می‌گیرد؟","شمال و جنوب مغناطیسی",["شرق و غرب جغرافیایی همیشه","بالا و پایین عمودی","جهت باد"],"عقربه قطب‌نما با میدان مغناطیسی زمین هم‌راستا می‌شود."),
("کدام پدیده باعث ایجاد جزر و مد در دریاها می‌شود؟","جاذبه ماه و خورشید",["فقط وزش باد","فقط باران","چرخش ابرها"],"جاذبه ماه و تا حدی خورشید در ایجاد جزر و مد نقش دارد."),
("کدام مورد نمونه‌ای از منبع آلودگی صوتی است؟","بوق و صدای بلند ترافیک",["برگ درخت در سکوت","نور ماه","آب آشامیدنی"],"صدای بلند و ناخواسته ترافیک می‌تواند آلودگی صوتی ایجاد کند."),
