# Persian: 50 sentence records x 3 grammar prompts = 150
sentences=[]
subs=["دانش‌آموز کوشا","پرنده کوچک","باغبان مهربان","معلم دانا","کودک خندان","باران بهاری","کارگر پرتلاش","مادر مهربان","پژوهشگر جوان","فروشنده منصف","ورزشکار سریع","نویسنده خلاق","کشاورز زحمتکش","دختر هنرمند","پسر کنجکاو","گربه بازیگوش","درخت بلند","قایق کوچک","مسافر خسته","پزشک دلسوز","نقاش ماهر","دوست صمیمی","کوه بلند","رود خروشان","دانشجوی پرتلاش","شاعر جوان","پرستار مهربان","ماهی رنگارنگ","پروانه زیبا","مرد دانا","زن هنرمند","دانش‌آموز دقیق","مربی باتجربه","کودک آرام","پرنده مهاجر","درخت کهنسال","دریای آبی","هواپیمای بزرگ","راننده محتاط","خیاط ماهر","نجار هنرمند","مادر بزرگوار","پدر دلسوز","داور منصف","دوچرخه‌سوار چابک","بازیگر مشهور","عکاس جوان","سرباز شجاع","همسایه مهربان","دانش‌آموز مسئول"]
verbs=["کتاب را خواند","به مدرسه رفت","گل‌ها را آبیاری کرد","داستانی نوشت","مسئله را حل کرد","به پرواز درآمد","درختی کاشت","به دوستش کمک کرد","نقاشی زیبایی کشید","با دقت گوش داد"]
for i,sub in enumerate(subs):
    verb=verbs[i%len(verbs)]
    sentence=sub+" "+verb+"."
    verbword=verb.split()[-1]
    adj=sub.split()[-1]
    # identify subject phrase as exact first token
    subject=sub
    words=list(dict.fromkeys([subject,verbword,adj,"را" if "را" in verb else "به", "کتاب" if "کتاب" in sentence else "مدرسه" ]))
    # correct verb choice: include 3 distractors from sentence words
    vd=[w for w in words if w!=verbword]
    while len(vd)<3: vd.append(random.choice(["زیبا","امروز","آرام","خانه"]))
    add("فارسی","آسان","شناخت فعل",f"در جمله «{sentence}» فعل کدام واژه است؟",[verbword]+vd[:3],verbword,f"فعل، انجام کار یا رخداد را نشان می‌دهد؛ در این جمله «{verbword}» فعل است.")
    adjs=[x for x in sub.split()[1:]]
    adj=adjs[0] if adjs else sub.split()[0]
    opts=[adj,verbword,subject,"را"]
    add("فارسی","متوسط","شناخت صفت",f"در عبارت «{sub}»، کدام واژه ویژگی اسم را بیان می‌کند؟",opts,adj,f"واژه «{adj}» ویژگی اسم را بیان می‌کند و صفت است.")
    nd=[x for x in [verbword,adj,"را","مدرسه","امروز","کتاب","گل"] if x!=subject]
    add("فارسی","متوسط","شناخت نهاد",f"در جمله «{sentence}»، نهاد یا کسی/چیزی که درباره‌اش خبر داده شده کدام است؟",[subject]+nd[:3],subject,f"نهاد جمله «{subject}» است؛ درباره او خبر داده شده است.")
assert len([x for x in qs if x['subject']=="فارسی"])==150

