religion=religion[:40]
for idx,(q,ans,wrong,exp) in enumerate(religion):
    add("قرآن و هدیه‌های آسمان","آسان" if idx%4==0 else "متوسط","قرآن، عبادت و اخلاق",q,[ans]+wrong,ans,exp)
