assert len([x for x in qs if x['subject']=="قرآن و هدیه‌های آسمان"])==120

# Balance difficulty levels across every subject so filters work for each one.
level_targets={
    "روش تدریس و رفتار معلم":(100,100),
    "ریاضی":(80,60),
    "علوم تجربی":(42,50),
    "فارسی":(50,30),
    "مطالعات اجتماعی":(30,36),
    "قرآن و هدیه‌های آسمان":(10,18),
}
for subject,(easy_count,hard_count) in level_targets.items():
    pool=[x for x in qs if x["subject"]==subject]
    random.shuffle(pool)
    for i,item in enumerate(pool):
        item["level"]="آسان" if i<easy_count else ("دشوار" if i<easy_count+hard_count else "متوسط")

# final validation
assert len(qs)==2000, len(qs)
from collections import Counter
cc=Counter(q['question'] for q in qs)
assert len({q['question'] for q in qs})==2000, "duplicate prompts"
assert len({q['id'] for q in qs})==2000
for q in qs:
    assert len(q['options'])==4 and 0<=q['answer']<4

# distribute in balanced deterministic order, so test sets aren't grouped by subject
random.shuffle(qs)
for i,q in enumerate(qs,1): q['id']=f"AQ{i:04d}"
root=pathlib.Path(__file__).resolve().parents[1]/'data'
root.mkdir(parents=True,exist_ok=True)
(root/'questions.json').write_text(json.dumps(qs,ensure_ascii=False,indent=2),encoding='utf-8')
summary={}
for q in qs: summary[q['subject']]=summary.get(q['subject'],0)+1
print('TOTAL',len(qs),'UNIQUE',len({q['question'] for q in qs}))
print(summary)
